// AllProjectRegionLogSubscriptions iterates over every object ListProjectRegionLogSubscriptions lists, fetching each one with
// GetProjectRegionLogSubscription only when the loop reaches it. An object deleted in the meantime is skipped; on
// any other error it yields the error and stops.
func (s *Service) AllProjectRegionLogSubscriptions(ctx context.Context, serviceName string, regionName string, params ...ListProjectRegionLogSubscriptionsParams) iter.Seq2[*DbaasLogsLogSubscription, error] {
	return ovh.Each(ctx,
		func(ctx context.Context) ([]string, error) {
			return s.ListProjectRegionLogSubscriptions(ctx, serviceName, regionName, params...)
		},
		func(ctx context.Context, listedID string) (*DbaasLogsLogSubscription, error) {
			return s.GetProjectRegionLogSubscription(ctx, serviceName, regionName, listedID)
		})
}

